package com.bananalab.lite;
import android.content.Context;import java.util.*;import java.util.regex.*;
final class ConversationAssist{
 static String reply(Context c,String input,SceneDraft d)throws Exception{String label=ContextEncoder.classify(c,input);
  if(label.equals("unknown"))return null;
  if(label.equals("recap"))return d==null?"Todavía no hay una escena. Podemos empezar por un personaje o una criatura combinable.":SceneGuide.summary(d)+"\nPodemos continuarla, corregir una parte o preparar otra toma.";
  if(label.equals("continue"))return d==null||d.cast.isEmpty()?"Primero elegimos los personajes. Después podés decir qué acción agregar.":"Para conservar la secuencia decí ‘continua con "+d.cast.get(0).display()+" saluda’. Si se llena esta toma, ‘prepara siguiente toma’ conserva sus diseños y el estado de los objetos.";
  if(label.equals("voice"))return "Podés escribir: Tony dice \"Hola, soy Tony\". Agrego una frase hablada con voz sintética propia y boca sincronizada. Para otro timbre: ‘voz de Tony grave’.";
  if(label.equals("voice_limits"))return "La voz es un sintetizador propio de sonidos y resonancias: robótica y experimental. No usa Android TTS, grabaciones ni modelos externos. Puede pronunciar de forma imperfecta.";
  if(label.equals("custom"))return "Podemos combinar seis cuerpos, orejas y cola. Probá ‘crea a Nube una criatura redonda azul con orejas largas y cola corta’. El editor tiene Forma, Orejas y Cola. Sigue siendo un estilo limitado, no dibujo universal.";
  if(label.equals("duration"))return "Podés pedir ‘hace que dure 30 segundos’. Cada toma admite hasta120 segundos; la serie de tomas, hasta300. Los diálogos necesitan tiempo suficiente para pronunciarse.";
  if(label.equals("objects"))return "Antes de entregar reviso quién sostiene el objeto en ese tiempo. ‘Tony entrega una caja a Milo’ crea una caja nueva; después solo su poseedor puede pasarla. Podés consultar quién la recibió o quién la tiene al final.";
  if(label.equals("correction"))return "Podemos cambiar solo una parte o deshacer. Por ejemplo: ‘cambia el sombrero de Tony por una corona y deja todo lo demas igual’. Si digo que una referencia es ambigua, podés responder con el nombre del personaje.";
  if(label.equals("memory"))return "‘Recorda que…’ guarda un dato explícito. ‘Mis recuerdos’ muestra sus números; ‘corregi el recuerdo 1: …’ y ‘olvida el recuerdo 1’ cambian solo ese dato. Los recuerdos no ejecutan órdenes de dibujo.";
  if(label.equals("audio"))return "El MP4 puede llevar ambiente, pasos y las frases escritas con la voz sintética propia. ‘Activa el sonido’ lo habilita; ‘sin sonido’ lo desactiva. Los GIF no incluyen audio.";
  if(label.equals("capability"))return "Puedo organizar escenas, conservar personajes, combinar criaturas, agregar diálogos con voz sintética y unir tomas. El modelo de conversación libre sigue siendo pequeño y experimental; estas herramientas trabajan con el proyecto guardado.";
  if(label.equals("ideas")){CreatorSession state=CreatorMemory.load(c);String proposal;if(d==null||d.cast.isEmpty())proposal="crea a Nube una criatura redonda azul con orejas largas y cola corta";else if(ObjectTransfer.beats(d)>=SceneTiming.MAX_BEATS)proposal="prepara siguiente toma";else{SceneDraft.Actor speaker=d.cast.get(0);String words="Hola, soy "+speaker.display();for(SceneDraft.Prop p:d.props){String owner=ObjectTransfer.at(d,p.id,1,ObjectTransfer.beats(d)).owner();if(!owner.isEmpty()){speaker=d.get(owner);words="Yo tengo la "+p.type;break;}}proposal=speaker.display()+" dice \""+words+"\"";}state.proposal=proposal;state.proposalScene=d==null?"":d.json().toString();CreatorMemory.save(c,state,null);return "Te propongo: "+proposal+".\nDecí ‘aplica esa idea’ si querés hacerlo, o contame qué cambiarías.";}
  return null;
 }
 static String natural(String input,SceneDraft base,CreatorSession c){String q=CreationRequest.normalize(input);Matcher m=Pattern.compile("(?:me gustaria|quisiera|podrias|podes|quiero) (?:ver a |que |hacer que )?(.+?) (baila|bailar|bailando|baile|salta|saltar|saltando|salte|camina|caminar|caminando|camine|saluda|saludar|saludando|salude)(?: por favor)?").matcher(q);Matcher alone=Pattern.compile("(?:quiero|quisiera|podes)(?: que| hacer que)? (baila|baile|salta|salte|camina|camine|saluda|salude)").matcher(q);if(base==null||!m.matches()&&!alone.matches())return input;String verb=m.matches()?m.group(2):alone.group(1);String action=verb.startsWith("bail")?"baila":verb.startsWith("salt")?"salta":verb.startsWith("camin")?"camina":"saluda";SceneDraft.Actor a=m.matches()?ScenePlanner.resolve(base,m.group(1),false):base.cast.size()==1?base.cast.get(0):null;if(a==null){c.clarifyTemplate="continua con __actor__ "+action;try{c.clarifyScene=base.json().toString();}catch(Exception ignored){}return "__ask_actor__";}return "continua con "+a.name+" "+action;}
}
